# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs[1:]]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(sift(render(intake(shape(raw)))))

